using static StrataLint.Scribe.DefinitionDsl;
using StrataLint.Scribe;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class NoncommutativeCentralReturnDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A central low return word forces a group generated by the marked pair to be commutative.",
        H("Central low return in a generated group"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("noncommutative-central-return-commutativity"),
                DeclarationHandle.Create(
                    "D5/S3/Geometry/Hyperideal/NoncommutativeCentralReturn.commutative_of_central_low_return"),
                H("Central low return implies commutativity"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text(
                        "Let u and v generate G. If every element of the generated subgroup commutes "
                        + "with the low return word v inverse times u squared, then u commutes with that "
                        + "word. The identity v = u squared times the inverse low return word then gives "
                        + "Commute(u,v). Since the two marked generators commute pairwise, their generated "
                        + "subgroup is commutative; the generation hypothesis makes every pair in G commute.")),
                    Paragraph(Text(
                        "The conclusion applies to arbitrary groups and does not assume finiteness, faithfulness "
                        + "of an action, or a geometric realization. In a noncommutative group generated by "
                        + "u and v, the low return word therefore cannot be central."))),
                DescribeRole.Theorem))));
}
